import json

def transform(grid):
    rows = len(grid)
    if rows == 0:
        return grid
    cols = len(grid[0])

    # Find the 2-line column (column with exactly one unique value in each row)
    two_line_col = None
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        unique_vals = set(col_vals)
        if len(unique_vals) == 1:
            two_line_col = c
            break

    if two_line_col is None:
        return grid

    # Find uniform columns (columns with all same value)
    uniform_cols = []
    for c in range(cols):
        col_vals = [grid[r][c] for r in range(rows)]
        if len(set(col_vals)) == 1:
            uniform_cols.append(c)

    # Find mixed columns (have both 0s and background)
    mixed_cols = []
    for c in range(cols):
        if c == two_line_col:
            continue
        col_vals = [grid[r][c] for r in range(rows)]
        if 0 in col_vals and col_vals.count(0) < rows - 1:  # Not all 0s, not uniform background
            mixed_cols.append(c)

    # Try to find a column to fill
    # Rule: fill the first uniform column to the right of the mixed region
    # starting from the two_line position

    for pos, c in enumerate(uniform_cols):
        if c > two_line_col:
            return make_grid_filled_col(grid, c, 8)

    return grid

def make_grid_filled_col(grid, col, fill_value):
    result = [row[:] for row in grid]  # Deep copy
    for r in range(len(result)):
        if result[r][col] == result[r][0]:  # Only fill uniform background columns
            result[r][col] = fill_value
    return result

